"""Reconcile June invoices against the bank statement (see backoffice/README.md).

Matching: memo carries the invoice number as inv<N>, INV-<N>, "invoice <N>", etc.
Category priority (exclusive): unpaid (0 payments) > duplicated (>1 payments) > mismatched
(exactly 1 payment whose amount differs from the invoice).
"""
import csv
import json
import re
from collections import defaultdict
from decimal import Decimal
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
INVOICES = ROOT / "backoffice" / "invoices.csv"
BANK = ROOT / "backoffice" / "bank_statement_june.csv"
OUT = ROOT / "result.json"

# Invoice numbers are the only 4-digit token prefixed by inv/invoice (any case,
# optional hyphen/space), which is how every memos in the statement cites them.
MEMO_INVOICE = re.compile(r"\b(?:inv|invoice)[\s-]*(\d{4})\b", re.IGNORECASE)


def money(text: str) -> Decimal:
    return Decimal(text.strip())


def load_invoices() -> dict[str, Decimal]:
    with INVOICES.open(newline="", encoding="utf-8") as fh:
        return {row["id"]: money(row["amount"]) for row in csv.DictReader(fh)}


def load_payments() -> dict[str, list[Decimal]]:
    payments: dict[str, list[Decimal]] = defaultdict(list)
    with BANK.open(newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            memo = row["memo"]
            match = MEMO_INVOICE.search(memo)
            if not match:
                continue  # fees, interest, unidentified PIX: ignored per README
            invoice_id = f"INV-{match.group(1)}"
            payments[invoice_id].append(money(row["amount"]))
    return payments


def reconcile() -> dict:
    invoices = load_invoices()
    payments = load_payments()
    unknown = sorted(set(payments) - set(invoices))
    if unknown:
        raise SystemExit(f"bank memo cites unknown invoice ids: {unknown}")

    unpaid, duplicated, mismatched = [], [], []
    for invoice_id, invoiced in invoices.items():
        paid = payments.get(invoice_id, [])
        if not paid:
            unpaid.append(invoice_id)
            continue
        if len(paid) > 1:
            duplicated.append(invoice_id)
            continue
        if paid[0] != invoiced:
            mismatched.append(
                {"id": invoice_id, "invoiced": float(invoiced), "paid": float(paid[0])}
            )

    for invoice_id in duplicated:
        print(f"duplicated {invoice_id}: payments {payments[invoice_id]}")
    for entry in mismatched:
        print(f"mismatched {entry['id']}: invoiced {entry['invoiced']} paid {entry['paid']}")
    print(f"unpaid: {unpaid}")
    print(f"bank lines matched: {sum(len(v) for v in payments.values())}")

    return {"unpaid": unpaid, "duplicated": duplicated, "mismatched": mismatched}


if __name__ == "__main__":
    result = reconcile()
    OUT.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {OUT}")

